/**
 * @suppress
 */
public object FfiConverterTypeSpoteEngine: FfiConverter<SpoteEngine, Long> {
    override fun lower(value: SpoteEngine): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): SpoteEngine {
        return SpoteEngine(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): SpoteEngine {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: SpoteEngine) = 8UL

    override fun write(value: SpoteEngine, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



data class AlbumDto (
    var `album`: kotlin.String
    ,
    var `artist`: kotlin.String
    ,
    var `trackCount`: kotlin.Long
    ,
    var `readyCount`: kotlin.Long
    ,
    var `durationMs`: kotlin.ULong
    ,
    var `artPath`: kotlin.String?
    ,
    var `artUrl`: kotlin.String?

){





    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAlbumDto: FfiConverterRustBuffer<AlbumDto> {
    override fun read(buf: ByteBuffer): AlbumDto {
        return AlbumDto(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterLong.read(buf),
            FfiConverterLong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
        )
    }

    override fun allocationSize(value: AlbumDto) = (
            FfiConverterString.allocationSize(value.`album`) +
            FfiConverterString.allocationSize(value.`artist`) +
            FfiConverterLong.allocationSize(value.`trackCount`) +
            FfiConverterLong.allocationSize(value.`readyCount`) +
            FfiConverterULong.allocationSize(value.`durationMs`) +
            FfiConverterOptionalString.allocationSize(value.`artPath`) +
            FfiConverterOptionalString.allocationSize(value.`artUrl`)
    )

    override fun write(value: AlbumDto, buf: ByteBuffer) {
            FfiConverterString.write(value.`album`, buf)
            FfiConverterString.write(value.`artist`, buf)
            FfiConverterLong.write(value.`trackCount`, buf)
            FfiConverterLong.write(value.`readyCount`, buf)
            FfiConverterULong.write(value.`durationMs`, buf)
            FfiConverterOptionalString.write(value.`artPath`, buf)
            FfiConverterOptionalString.write(value.`artUrl`, buf)
    }
}



