sealed class SpoteException: kotlin.Exception() {

    class Library(

        val `detail`: kotlin.String
        ) : SpoteException() {
        override val message
            get() = "detail=${ `detail` }"
    }

    class Io(

        val `detail`: kotlin.String
        ) : SpoteException() {
        override val message
            get() = "detail=${ `detail` }"
    }

    class Image(

        val `detail`: kotlin.String
        ) : SpoteException() {
        override val message
            get() = "detail=${ `detail` }"
    }

    class Catalog(

        val `detail`: kotlin.String
        ) : SpoteException() {
        override val message
            get() = "detail=${ `detail` }"
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SpoteException> {
        override fun lift(error_buf: RustBuffer.ByValue): SpoteException = FfiConverterTypeSpoteError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeSpoteError : FfiConverterRustBuffer<SpoteException> {
    override fun read(buf: ByteBuffer): SpoteException {


        return when(buf.getInt()) {
            1 -> SpoteException.Library(
                FfiConverterString.read(buf),
                )
            2 -> SpoteException.Io(
                FfiConverterString.read(buf),
                )
            3 -> SpoteException.Image(
                FfiConverterString.read(buf),
                )
            4 -> SpoteException.Catalog(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SpoteException): ULong {
        return when(value) {
            is SpoteException.Library -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is SpoteException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is SpoteException.Image -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is SpoteException.Catalog -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: SpoteException, buf: ByteBuffer) {
        when(value) {
            is SpoteException.Library -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is SpoteException.Io -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is SpoteException.Image -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is SpoteException.Catalog -> {
                buf.putInt(4)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
